class Solution {
    int get(unordered_map<long long,int>& map,long long key){
        return map[key];
    }
    public: int waysToPartition(vector<int>& nums,int k){
        long long total=accumulate(nums.begin(),nums.end(),0LL),prefix=0;
        vector<long long> difference(nums.size());
        unordered_map<long long,int> left,right;
        for(int pivot=1;pivot<(int)nums.size();++pivot){
            prefix+=nums[pivot-1];
            difference[pivot]=2*prefix-total;
            ++right[difference[pivot]];
        }
        int answer=right[0];
        for(int index=0;index<(int)nums.size();++index){
            if(index){
                long long value=difference[index];
                --right[value];
                ++left[value];
            }
            long long delta=(long long)k-nums[index];
            answer=max(answer,left[delta]+right[-delta]);
        }
        return answer;
    }
};
